class Solution {
public:
    int findMaxPathScore(vector<vector<int>>& edges, vector<bool>& online, long long k) {
        int n = online.size();
        int m = edges.size();
        // CSR adjacency
        vector<int> head(n, -1), nxt(m), to(m), ecost(m);
        vector<int> indeg(n, 0);
        for (int i = 0; i < m; ++i) {
            to[i] = edges[i][1];
            ecost[i] = edges[i][2];
            nxt[i] = head[edges[i][0]];
            head[edges[i][0]] = i;
            indeg[edges[i][1]]++;
        }
        // topological order (Kahn), computed once on full graph
        vector<int> order;
        order.reserve(n);
        vector<int> deg = indeg;
        vector<int> q;
        q.reserve(n);
        for (int i = 0; i < n; ++i) if (deg[i] == 0) q.push_back(i);
        for (size_t qi = 0; qi < q.size(); ++qi) {
            int u = q[qi];
            order.push_back(u);
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (--deg[to[e]] == 0) q.push_back(to[e]);
            }
        }
        // distinct sorted costs
        vector<int> costs;
        costs.reserve(m);
        for (int i = 0; i < m; ++i) costs.push_back(ecost[i]);
        sort(costs.begin(), costs.end());
        costs.erase(unique(costs.begin(), costs.end()), costs.end());
        int t = costs.size();
        if (t == 0) return -1;
        const long long INF = (long long)4e18;
        vector<long long> dist(n);
        auto feasible = [&](int thr) -> bool {
            for (int i = 0; i < n; ++i) dist[i] = INF;
            dist[0] = 0;
            for (int idx = 0; idx < n; ++idx) {
                int u = order[idx];
                if (dist[u] == INF) continue;
                if (!online[u]) continue;
                for (int e = head[u]; e != -1; e = nxt[e]) {
                    if (ecost[e] < thr) continue;
                    int v = to[e];
                    long long nd = dist[u] + ecost[e];
                    if (nd < dist[v]) dist[v] = nd;
                }
            }
            return dist[n - 1] <= k;
        };
        int lo = 0, hi = t - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (feasible(costs[mid])) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans == -1 ? -1 : costs[ans];
    }
};
